[
  {
    "id": "get_cart_eventually",
    "text": "A shopper is obligated to obtain a cart at some point during the trip.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    }
  },
  {
    "id": "use_cart_bay",
    "text": "A shopper is obligated to interact at the cart bay at (1,7).",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": {
        "and": [
          "at(1,7)",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "cart_for_roaming",
    "text": "A shopper may move without a cart only near the entrance/cart bay or in the narrow aisle around (6,1)-(6,3).",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": {
              "or": [
                "at(0,7)",
                "at(1,7)",
                "at(6,1)",
                "at(6,2)",
                "at(6,3)"
              ]
            }
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_upper_aisle",
    "text": "Carts are prohibited in the upper narrow aisle cells (6,1) and (6,2).",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          {
            "or": [
              "at(6,1)",
              "at(6,2)"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "no_north_with_cart_at_63",
    "text": "A shopper is prohibited from moving north from (6,3) while holding a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "at(6,3)",
          "hasCart",
          "N"
        ]
      }
    }
  },
  {
    "id": "item_interaction_no_cart",
    "text": "A shopper is prohibited from interacting at (6,1) while holding a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "at(6,1)",
          "hasCart",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "reclaim_cart",
    "text": "Whenever a shopper is without a cart, they are obligated to have a cart again before the trajectory ends.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": {
        "not": "hasCart"
      },
      "discharge": "hasCart"
    }
  },
  {
    "id": "exit_with_cart",
    "text": "A shopper is prohibited from exiting the store without a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  }
]
